        val entry=pool.read(key(),revision());check(entry.sourceHash==sourceHash()){ "Provider source changed; read the exact version again" }
        require(text().isNotBlank() && text().length<=8000){"A note needs 1 to 8000 characters"}
        require(actor().isNotBlank() && actor().length<=120 && evidence().size<=16 && evidence().all{it.length in 1..2048}){"Invalid note author or evidence references"}
        val id=UUID.randomUUID().toString()
        val note=mapOf("id" to id,"key" to entry.key,"revision" to entry.revision,"sourceHash" to entry.sourceHash,
            "at" to Instant.now().toString(),"actor" to actor(),"text" to text(),"evidence" to evidence(),
            "originDocument" to poolDocument.filename,"originBox" to poolOwner.id)
        val folder=java.io.File(pool.directory,"${entry.key}/notes/${entry.revision}").apply{mkdirs()}
        val tmp=Files.createTempFile(folder.toPath(),".note-",".tmp")
        try {
            poolJson.writerWithDefaultPrettyPrinter().writeValue(tmp.toFile(),note)
            Files.move(tmp,folder.resolve("$id.json").toPath(),StandardCopyOption.ATOMIC_MOVE)
        } finally {Files.deleteIfExists(tmp)}
        note
    }
}
