    describe("Inspect tools actually registered in this document, or one tool's schema, provider source identity, attached examples, recent call inputs/results/errors and test outcomes. This is the same registry used by AI4 and MCP.")
    val name by param<String>("Empty lists the document's tools",default="")
    action {
        val tools=if(name().isBlank())DocumentToolRegistry.toolsFor(poolDocument.filename) else listOf(localTool(name()))
        tools.map{mapOf("name" to it.name,"description" to it.description,"box" to it.boxId,"sourceHash" to it.sourceHash,
            "schema" to it.parametersSchema.toString(),"checks" to it.diagnostics.tests(),
            "calls" to if(name().isBlank()) emptyList() else it.diagnostics.calls(),"storageError" to it.diagnostics.storageError)}
    }
}
aiTool("pool.test") {
    describe("Explicitly run one registered tool's attached examples through its real argument binding and execution. Use a disposable project for tools that edit state. An empty suite is untested, not green. Requires the exact registered source hash.")
    val name by param<String>(); val sourceHash by param<String>()
    action {val tool=localTool(name());check(tool.sourceHash==sourceHash()){ "Tool changed; inspect it again" };val results=tool.test();mapOf("tested" to results.isNotEmpty(),"passed" to (results.isNotEmpty()&&results.all{it.passed}),"checks" to results)}
}
aiTool("pool.publish") {
    describe("Explicitly curate a provider box into the local tool pool for reuse across projects. Stores the whole provider source and its source-specific tests, not runtime objects or private dependencies. Name dependencies in the description. Does not publish to Git or any network service.")
    val boxId by param<String>(); val key by param<String>(); val description by param<String>(); val sourceHash by param<String>()
