}
fun showPool() {
    fun esc(v:Any?)=v.toString().replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;")
    val curated=pool.list().joinToString(""){entry ->
        val notes=notesFor(entry["key"].toString(),entry["revision"].toString())
        val checks=(entry["checks"] as? Map<*,*>)?.values?.filterIsInstance<ToolTestEvidence>()?.flatMap{it.tests}.orEmpty()
        val state=if(checks.isEmpty())"Untested" else if(checks.all{it.passed})"${checks.size} checks passed in the source project" else "${checks.count{!it.passed}} checks failed"
        "<details style='margin:14px 0'><summary>${esc(entry["key"])} · $state · ${notes.size} notes</summary><p>${esc(entry["description"])}</p><p style='color:#999;overflow-wrap:anywhere;user-select:text'>Version ${esc(entry["revision"])}</p><p>Read this version with pool.read, run it in a provider box, and test it in the destination project.</p>"+notes.takeLast(10).joinToString(""){n->"<details><summary>${esc(n["actor"])} · ${esc(n["at"])}</summary><p style='white-space:pre-wrap;user-select:text'>${esc(n["text"])}</p><pre style='white-space:pre-wrap;overflow-wrap:anywhere;user-select:text'>${esc((n["evidence"] as? List<*>)?.joinToString("\n").orEmpty())}</pre></details>"}+"</details>"
    }
