                  // Keep a little yaw as well, bounded, so mode 3 still has a trailing edge to show.
                  val yawWanted = sin(t * 0.45) * YAW_AMPLITUDE
                  bundle.scene.camera.yaw(yawWanted - yawApplied, aroundTarget = false)
                  yawApplied = yawWanted
